// Computes the 3-tier lookup paths (database override -> org override -> standard) from
// the caller's raw process path -- moved in here once Batch Processing became this
// sub-workflow's 2nd real caller, duplicating the exact same derivation SAP: Process Form
// Filling already did before calling this workflow.
const base = $json;
const ref = base.github_tag || 'main';
const orgSlug = base.organization?.slug || '';
const companyDB = base.session?.database || '';
const pathSegs = (base.path || '').split('/');
const filename = pathSegs[pathSegs.length - 1];
const module = base.module || pathSegs[pathSegs.length - 2] || '';
const pathPrefix = pathSegs[0] || '';
return [{ json: {
  ...base,
  standard_path: base.path,
  org_standard_path: `${pathPrefix}/${orgSlug}/standard/${module}/${filename}`,
  database_path: `${pathPrefix}/${orgSlug}/${companyDB}/${module}/${filename}`,
  github_ref: ref,
  github_api_base: `https://api.github.com/repos/${base.github_owner}/${base.github_repo}/contents`,
} }];

const fileData = $json;
const original = $('Compute Schema Paths').first().json;
const statusCode = fileData.statusCode;
if (fileData.error || (statusCode && statusCode >= 400)) {
  return [{ json: { process_definition: null, error: 'NOT_FOUND', error_message: 'No se encontró la definición del proceso.', schema_fetch_url: null } }];
}
const rawContent = (fileData.body || fileData).content;
let processDefinition;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  processDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { process_definition: null, error: 'NOT_FOUND', error_message: 'Error al parsear la definición del proceso.', schema_fetch_url: null } }];
}
const filePath = (fileData.body || fileData).path || '';
const fileDir = filePath ? filePath.substring(0, filePath.lastIndexOf('/')) : '';
const schemaSlug = processDefinition.schema || '';
const schemaFetchUrl = (fileDir && schemaSlug && original.github_api_base)
  ? `${original.github_api_base}/${fileDir}/${schemaSlug}.json?ref=${original.github_ref || 'main'}`
  : null;
return [{ json: { process_definition: processDefinition, error: null, error_message: null, schema_fetch_url: schemaFetchUrl } }];

const fileData = $json;
const prevData = $('Decode Process Definition').first().json;
// Always spread the original trigger input forward, same convention every agent
// sub-workflow's own Recover State node already follows -- makes this sub-workflow's
// output self-contained regardless of which of its (possibly multiple) callers invoked
// it, instead of requiring the caller to guess which of its own ancestor nodes to merge
// back with.
const original = $('Execute Workflow Trigger').first().json;
if (!prevData.schema_fetch_url || fileData.error || (fileData.statusCode && fileData.statusCode >= 400)) {
  return [{ json: { ...original, process_definition: prevData.process_definition, error: prevData.error, error_message: prevData.error_message } }];
}
const rawContent = (fileData.body || fileData).content;
let schemaDefinition = null;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  schemaDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { ...original, process_definition: prevData.process_definition, error: prevData.error, error_message: prevData.error_message } }];
}
const processDefinition = prevData.process_definition
  ? { ...prevData.process_definition, schema_definition: schemaDefinition }
  : prevData.process_definition;
return [{ json: { ...original, process_definition: processDefinition, error: null, error_message: null } }];
